script:
if (-not $IP) { throw 'IP is required' }
$adapters = @(Get-NetAdapter | Where-Object Status -eq 'Up' | Sort-Object ifIndex)
if ($adapters.Count -lt 2) {
    Write-Warning 'no second NIC present (add the NIC hypervisor-side before planting); no-op'
    exit 0
}
if (-not $PREFIX)  { $PREFIX  = '24' }
if (-not $DNS1)    { $DNS1    = '1.1.1.1' }
if (-not $DNS2)    { $DNS2    = '8.8.8.8' }
if ($INTERFACE_ALIAS) {
    $nic = $adapters | Where-Object Name -eq $INTERFACE_ALIAS
} else {
    $nic = $adapters[1]
}
if (-not $nic) { throw "adapter '$INTERFACE_ALIAS' not found among the up adapters" }
$existing = Get-NetIPAddress -InterfaceAlias $nic.Name -IPAddress $IP -ErrorAction Ignore
if (-not $existing) {
    New-NetIPAddress -InterfaceAlias $nic.Name -IPAddress $IP -PrefixLength ([int]$PREFIX) | Out-Null
}
Set-DnsClientServerAddress -InterfaceAlias $nic.Name -ServerAddresses @($DNS1, $DNS2)
Write-Output "WAN-range NIC configured: $($nic.Name) = $IP/$PREFIX dns $DNS1,$DNS2"
